const response = $input.first().json;
const script = response.choices[0].message.content.trim();

if (!script || script.length < 50) {
  throw new Error('Script too short or empty: ' + script);
}

if (script.length > 900) {
  throw new Error('Script too long (' + script.length + ' chars). Adjust GPT prompt.');
}

console.log('Script length:', script.length, 'chars');
console.log('Script:', script);

return [{
  json: {
    ...($node['Extract & Clean Text'].json),
    script,
    scriptLength: script.length
  }
}];

const audioData = $input.first().binary?.data;
const json = $input.first().json;

if (!audioData) {
  throw new Error('No audio binary data received from ElevenLabs');
}

// Получаем base64 строку аудио
const audioBase64 = audioData.data;
const audioMimeType = audioData.mimeType || 'audio/mpeg';

console.log('Audio received, mime:', audioMimeType);

return [{
  json: {
    ...json,
    audioBase64,
    audioMimeType
  },
  binary: {
    data: audioData
  }
}];

const uploadResponse = $input.first().json;
const previousData = $node['Validate Script'].json;

const audioAssetId = uploadResponse?.data?.id || uploadResponse?.id;

if (!audioAssetId) {
  throw new Error('Failed to get audio_asset_id from HeyGen: ' + JSON.stringify(uploadResponse));
}

console.log('Audio asset ID:', audioAssetId);

return [{
  json: {
    ...previousData,
    audioAssetId
  }
}];

const response = $input.first().json;
const previousData = $node['Extract Audio Asset ID'].json;

const videoId = response?.data?.video_id || response?.video_id;

if (!videoId) {
  throw new Error('Failed to get video_id from HeyGen: ' + JSON.stringify(response));
}

console.log('Video generation started, ID:', videoId);

return [{
  json: {
    ...previousData,
    videoId,
    generationStartedAt: new Date().toISOString()
  }
}];

const statusResponse = $input.first().json;
const previousData = $node['Extract Video ID'].json;

const status = statusResponse?.data?.status || statusResponse?.status;
const videoUrl = statusResponse?.data?.video_url || statusResponse?.video_url;
const thumbnailUrl = statusResponse?.data?.thumbnail_url || '';

console.log('Video status:', status);

if (status === 'failed') {
  throw new Error('HeyGen video generation failed: ' + JSON.stringify(statusResponse));
}

return [{
  json: {
    ...previousData,
    status,
    videoUrl: videoUrl || null,
    thumbnailUrl,
    checkedAt: new Date().toISOString()
  }
}];

const videoData = $input.first().binary?.data;
const json = $input.first().json;

if (!videoData) {
  throw new Error('No video binary data received');
}

// Генерируем имя файла
const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
const safeTitle = (json.title || 'video').replace(/[^a-zA-Z0-9]/g, '_').slice(0, 30);
const filename = `${timestamp}_${safeTitle}.mp4`;

console.log('Video downloaded, saving as:', filename);

return [{
  json: {
    ...json,
    filename,
    savedAt: new Date().toISOString(),
    status: 'completed'
  },
  binary: {
    data: {
      ...videoData,
      fileName: filename,
      mimeType: 'video/mp4'
    }
  }
}];
